  if(compute==~0u)compute=graphics;if(transfer==~0u)transfer=compute;if(graphics==~0u)throw std::runtime_error("No graphics family");
  std::vector<uint32_t>families={graphics,compute,transfer};std::sort(families.begin(),families.end());families.erase(std::unique(families.begin(),families.end()),families.end());
  VkPhysicalDeviceTimelineSemaphoreFeatures available{VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_TIMELINE_SEMAPHORE_FEATURES};VkPhysicalDeviceFeatures2 features{VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2};features.pNext=&available;vkGetPhysicalDeviceFeatures2(gpu.physical,&features);if(!available.timelineSemaphore)throw std::runtime_error("Real timeline feature unavailable");
